const arr = (v) => (Array.isArray(v) ? v : []);
const isObj = (v) => !!v && typeof v === 'object';
const listingsOf = (ctx) => arr(ctx.db?.prListings).filter((l) => isObj(l) && typeof l.id === 'string' && typeof l.name === 'string');
